def calculate_S(N):
    """Calculates S(N) = sum_{a=1}^N sum_{b=1}^N floor(ab/(N+1))."""
    S_N = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S_N += (a * b) // (N + 1)
    return S_N

def calculate_T(N):
    """Calculates the target value T(N) = (N^3 - N^2 + 2) / 4."""
    return (N**3 - N**2 + 2) / 4

N_values = [5, 6, 7]
results = {}

for N in N_values:
    S_N = calculate_S(N)
    T_N = calculate_T(N)

    # Check if T_N is an integer before comparing strictly, as S_N must be an integer.
    T_N_int = T_N if T_N == int(T_N) else None

    results[N] = {
        "S(N)": S_N,
        "T(N)": T_N,
        "T(N)_int": T_N_int
    }

print("Results:")
for N, data in results.items():
    print(f"N={N}:")
    print(f"  S({N}) = {data['S(N)']}")
    print(f"  T({N}) = {data['T(N)']}")
    if data['T(N)_int'] is not None:
        print(f"  T({N}) is integer: {data['T(N)_int']}")
    else:
        print(f"  T({N}) is NOT integer.")

